const loadBook=async(poetId,bookId)=>{const key=poetId+'/'+bookId;if(bookCache.has(key))return bookCache.get(key);const rows=(await fetchGzipJson('data/poems/'+encodeURIComponent(poetId)+'__'+encodeURIComponent(bookId)+'.bin')).q,byId=new Map(rows.map(r=>[r[0],r]));(poemsByBook[key]||[]).forEach(item=>{const row=byId.get(item.id);if(row){item.title=row[1];item.couples=row[2];item.loaded=true}});const ready=poemsByBook[key]||[];bookCache.set(key,ready);return ready};
const ensurePoemLoaded=async poem=>{if(poem&&!poem.loaded)await loadBook(poem.poetId,poem.bookId);return poem};
let searchPromise=null;
