const app=document.getElementById('app'),fa=n=>Number(n||0).toLocaleString('fa-IR'),readJSON=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key)||JSON.stringify(fallback))}catch{return fallback}},norm=s=>String(s??'').toLocaleLowerCase('fa').replace(/[يى]/g,'ی').replace(/ك/g,'ک').replace(/[ۀة]/g,'ه').replace(/ـ/g,'').replace(/‌/g,'').replace(/\s+/g,' ').trim(),getId=p=>p.poetId+'/'+p.bookId+'/'+p.id;
