const bios={moulavi:'جلال‌الدین محمد بلخی، مشهور به مولانا، در ۶۰۴ق در بلخ زاده شد و بیشتر عمر خود را در قونیه گذراند. مثنوی و غزل‌های او از مهم‌ترین آثار عرفان فارسی‌اند.',hafez:'خواجه شمس‌الدین محمد حافظ شیرازی، شاعر سدهٔ هشتم هجری، در شیراز زیست و به‌ویژه برای غزل‌های چندلایه و موسیقایی‌اش شناخته می‌شود.',khayyam:'عمر خیام نیشابوری، زادهٔ ۴۳۹ق، ریاضی‌دان، منجم، فیلسوف و رباعی‌سرای ایرانی بود و در تدوین گاه‌شماری جلالی نقش داشت.',saadi:'مشرف‌الدین مصلح سعدی شیرازی، شاعر سدهٔ هفتم هجری، پس از سال‌ها سفر به شیراز بازگشت. بوستان و گلستان از آثار ماندگار او هستند.',saeb:'صائب تبریزی، شاعر سدهٔ یازدهم هجری، از برجسته‌ترین غزل‌سرایان سبک هندی است و به تصویرسازی و مضمون‌پردازی مشهور است.',attar:'فریدالدین عطار نیشابوری، شاعر و عارف سدهٔ ششم و هفتم هجری، در نیشابور می‌زیست و منطق‌الطیر از شناخته‌شده‌ترین آثار اوست.',babataher:'باباطاهر عریان، شاعر دوبیتی‌سرای منسوب به همدان، از چهره‌های کهن شعر عامیانه و عارفانهٔ فارسی است.'};
const bookFacts={'masnavi-daftar1':'مثنوی معنوی در شش دفتر سروده شده است؛ این دفتر نخست با داستان نی‌نامه آغاز می‌شود و روایت‌های عرفانی و اخلاقی را پیش می‌برد.','masnavi-daftar2':'دفتر دوم مثنوی ادامهٔ روایت‌های تمثیلی مولاناست؛ داستان‌ها برای توضیح مفاهیم عرفانی و اخلاقی به کار می‌روند.','masnavi-daftar3':'دفتر سوم مثنوی بخشی از منظومهٔ شش‌دفترهٔ مولاناست و میان حکایت‌های پیوسته، گفت‌وگو و تمثیل حرکت می‌کند.','masnavi-daftar4':'دفتر چهارم مثنوی از دفترهای میانی این منظومهٔ عرفانی است و مانند دیگر دفترها روایت و تفسیر را در هم می‌آمیزد.','masnavi-daftar5':'دفتر پنجم مثنوی مجموعه‌ای از حکایت‌ها و گفتارهای عرفانی است که با زبان داستانی به معنا می‌رسد.','masnavi-daftar6':'دفتر ششم، واپسین دفتر مثنوی معنوی، ادامهٔ همان مسیر روایی و تعلیمی مولاناست.','divan-shams':'دیوان شمس مجموعهٔ غزل‌ها و رباعی‌های مولاناست که به یاد شمس تبریزی این نام را گرفته است.','ghazal':'غزل‌های حافظ در سدهٔ هشتم هجری سروده شدند و دیوان او پس از درگذشتش گردآوری و تدوین شد.','ghete':'قطعات حافظ شعرهایی کوتاه‌تر از غزل‌اند و وجهی روایی، حکمی یا مناسبتی دارند.','ghaside':'قصاید حافظ بخش کوچک‌تری از میراث او را تشکیل می‌دهند و در قالب قصیده سروده شده‌اند.','robaee':'رباعی قالبی چهارمصراعی است؛ رباعیات منسوب به حافظ در کنار غزل‌ها در نسخه‌های دیوان آمده‌اند.','masnavi':'مثنوی‌های حافظ از آثار کوتاه‌تر او هستند و در قالب مثنوی، با روایت و مضمون عرفانی، سروده شده‌اند.','saghiname':'ساقی‌نامه شعری خطاب به ساقی است و در سنت شعر فارسی برای بیان شور، بی‌قراری و معنا به کار می‌رود.','boostan':'سعدی بوستان را در ۶۵۵ق به نظم درآورد؛ منظومه‌ای اخلاقی و حکایتی که فصل‌های آن دربارهٔ رفتار و زندگی انسانی است.','manteghotteyr':'منطق‌الطیر داستان سفر پرندگان برای یافتن سیمرغ است؛ در پایان، سی مرغ حقیقتی را که می‌جویند در خود می‌یابند.','2beytiha':'دوبیتی‌های باباطاهر با زبان ساده و عاطفی، از عشق، فراق و تجربهٔ عرفانی سخن می‌گویند.'};
